import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { cargoPackageName, syncVersion, updateCargoLockVersion } from './sync-version.mjs'

const repoRoot = resolve(__dirname, '..')

const CARGO_TOML = ['[package]', 'name = "scrivon"', 'version = "1.4.2"', '', '[lib]', 'name = "diagram_app_lib"', ''].join('\r\n')

const CARGO_LOCK = [
    '# This file is automatically @generated by Cargo.',
    'version = 4',
    '',
    '[[package]]',
    'name = "scrivo"',
    'version = "0.3.0"',
    '',
    '[[package]]',
    'name = "scrivon"',
    'version = "1.4.1"',
    'dependencies = [',
    ' "serde",',
    ']',
    '',
    '[[package]]',
    'name = "serde"',
    'version = "1.0.228"',
    '',
].join('\r\n')

describe('updateCargoLockVersion', () => {
    it("sets only the app's own version and keeps the line endings", () => {
        const updated = updateCargoLockVersion(CARGO_LOCK, 'scrivon', '1.5.0-rc.1')

        expect(updated).toBe(CARGO_LOCK.replace('name = "scrivon"\r\nversion = "1.4.1"', 'name = "scrivon"\r\nversion = "1.5.0-rc.1"'))
        expect(updated).toContain('name = "scrivo"\r\nversion = "0.3.0"')
        expect(updated).toContain('name = "serde"\r\nversion = "1.0.228"')
    })

    it('keeps LF line endings too', () => {
        const lf = CARGO_LOCK.replace(/\r\n/g, '\n')

        expect(updateCargoLockVersion(lf, 'scrivon', '1.5.0')).toBe(lf.replace('version = "1.4.1"', 'version = "1.5.0"'))
    })

    it('fails when the package is not in the lockfile', () => {
        expect(() => updateCargoLockVersion(CARGO_LOCK, 'diagram-app', '1.5.0')).toThrow(
            'Could not find the diagram-app package in src-tauri/Cargo.lock'
        )
    })
})

describe('cargoPackageName', () => {
    it('reads the [package] name, not the [lib] one', () => {
        expect(cargoPackageName(CARGO_TOML)).toBe('scrivon')
    })

    it("matches the app's real Cargo.toml and Cargo.lock", () => {
        const name = cargoPackageName(readFileSync(join(repoRoot, 'src-tauri', 'Cargo.toml'), 'utf8'))
        const lock = readFileSync(join(repoRoot, 'src-tauri', 'Cargo.lock'), 'utf8')

        expect(() => updateCargoLockVersion(lock, name, '9.9.9')).not.toThrow()
    })
})

describe('syncVersion', () => {
    let root: string

    beforeEach(() => {
        root = mkdtempSync(join(tmpdir(), 'scrivon-sync-version-'))
        mkdirSync(join(root, 'src-tauri'))
        mkdirSync(join(root, 'lib', 'legal'), { recursive: true })
        writeFileSync(join(root, 'package.json'), JSON.stringify({ name: 'scrivon', version: '1.5.0' }))
        writeFileSync(join(root, 'src-tauri', 'Cargo.toml'), CARGO_TOML)
        writeFileSync(join(root, 'src-tauri', 'Cargo.lock'), CARGO_LOCK)
        writeFileSync(join(root, 'src-tauri', 'tauri.conf.json'), JSON.stringify({ productName: 'Scrivon', version: '1.4.1' }))
        writeFileSync(join(root, 'lib', 'legal', 'app-version.ts'), "// The app's version.\r\nexport const APP_VERSION = '1.4.1'\r\n")
    })

    afterEach(() => {
        rmSync(root, { recursive: true, force: true })
    })

    it('copies the package.json version into every version file, Cargo.lock included', () => {
        expect(syncVersion(root)).toBe('1.5.0')

        const read = (...path: string[]) => readFileSync(join(root, ...path), 'utf8')
        expect(read('src-tauri', 'Cargo.toml')).toContain('version = "1.5.0"')
        expect(read('src-tauri', 'Cargo.lock')).toContain('name = "scrivon"\r\nversion = "1.5.0"')
        expect(read('src-tauri', 'Cargo.lock')).toContain('name = "scrivo"\r\nversion = "0.3.0"')
        expect(JSON.parse(read('src-tauri', 'tauri.conf.json')).version).toBe('1.5.0')
        // The comment and the Windows line endings are kept.
        expect(read('lib', 'legal', 'app-version.ts')).toBe("// The app's version.\r\nexport const APP_VERSION = '1.5.0'\r\n")
    })

    it('keeps the version in app-version.ts in step with package.json', () => {
        const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8')) as { version: string }
        expect(readFileSync(join(repoRoot, 'lib', 'legal', 'app-version.ts'), 'utf8')).toContain(`export const APP_VERSION = '${pkg.version}'`)
    })
})
